def average_spend_per_item_this_month(account):
    """Average spend, in cents, per item bought in the current month.

    Accounts with no purchases in the current month have no per-item
    average, so report 0 rather than dividing by zero.
    """
    bought = [p for p in account.purchases if p.in_current_month]
    if not bought:
        return 0
    return account.total_this_month_cents // len(bought)

class Account:
    def __init__(self, purchases, total_cents, total_this_month_cents):
        self.purchases = purchases
        self.total_cents = total_cents
        self.total_this_month_cents = total_this_month_cents

from io_shop.accounts import Account
from io_shop.spend_summary import average_spend_per_item_this_month


class FakePurchase:
    def __init__(self, in_current_month):
        self.in_current_month = in_current_month


def test_the_monthly_average_is_correct_for_a_shopper_who_did_buy():
    account = Account(
        purchases=[FakePurchase(True), FakePurchase(True)],
        total_cents=5000,
        total_this_month_cents=3000,
    )

    assert average_spend_per_item_this_month(account) == 1500


def test_a_shopper_with_no_purchases_at_all_averages_zero():
    account = Account(purchases=[], total_cents=0, total_this_month_cents=0)

    assert average_spend_per_item_this_month(account) == 0


def test_a_shopper_who_bought_nothing_this_month_averages_zero():
    account = Account(
        purchases=[FakePurchase(False), FakePurchase(False)],
        total_cents=5000,
        total_this_month_cents=0,
    )

    assert average_spend_per_item_this_month(account) == 0


def test_purchases_outside_the_current_month_are_not_counted():
    account = Account(
        purchases=[FakePurchase(True), FakePurchase(False), FakePurchase(False)],
        total_cents=9000,
        total_this_month_cents=2500,
    )

    assert average_spend_per_item_this_month(account) == 2500


def test_a_zero_month_total_with_purchases_averages_zero():
    account = Account(
        purchases=[FakePurchase(True)],
        total_cents=100,
        total_this_month_cents=0,
    )

    assert average_spend_per_item_this_month(account) == 0
